//! Golden output pin for the vocal melody passes.
//!
//! `derive_vocal_*` is seeded and its notes are persisted in user
//! projects: if the motif re-skin, the srdc layout, the climax pass or
//! the cadence formulas change what they emit — or merely change how
//! many values they draw from their RNGs — existing songs are rewritten
//! the next time they regenerate. The "same seed twice in one process"
//! checks in `tests/vocal.rs` cannot catch that, because they re-run
//! the *new* code both times.
//!
//! This test pins concrete notes for a matrix of styles, seeds, meters
//! and motifs against values recorded before the melody.rs split of ba
//! todo #1251. A failure here means generated vocal lines changed: a
//! user-visible change, never a test to re-bless casually.

#![allow(clippy::field_reassign_with_default)]

use resonance_music_theory::{
    derive_vocal_with_motif, generate_lyrics, vocal_phrase_spans, Chord, ChordQuality, PitchClass,
    TimedChord, VocalContour, VocalParams, VocalStyle, VoiceType,
};

fn chords() -> Vec<TimedChord> {
    let spec = [
        (PitchClass::B, ChordQuality::Min),
        (PitchClass::Fs, ChordQuality::Maj),
        (PitchClass::G, ChordQuality::Maj),
        (PitchClass::E, ChordQuality::Min),
    ];
    spec.iter()
        .enumerate()
        .map(|(i, &(root, quality))| TimedChord {
            chord: Chord::new(root, quality),
            start_beat: i as u32 * 4,
            duration_beats: 4,
        })
        .collect()
}

const STYLES: [VocalStyle; 6] = [
    VocalStyle::PopBallad,
    VocalStyle::Anthemic,
    VocalStyle::Conversational,
    VocalStyle::Folk,
    VocalStyle::Hymnal,
    VocalStyle::Chant,
];

const MOTIF: [i8; 4] = [0, 2, -1, 4];

/// Render one configuration as a stable line.
fn render(
    label: &str,
    style: VocalStyle,
    contour: VocalContour,
    voice: VoiceType,
    beats_per_bar: u32,
    motif: Option<&[i8]>,
    seed: u64,
) -> String {
    let mut p = VocalParams::default();
    p.style = style;
    p.contour = contour;
    p.voice = voice;
    p.range = voice.default_range();
    p.use_section_motif = motif.is_some();
    p.draft = generate_lyrics(&p, seed);

    let notes = derive_vocal_with_motif(&chords(), &p, 480, beats_per_bar, motif, seed);
    let rendered: Vec<String> = notes
        .iter()
        .map(|n| {
            format!(
                "{}@{}+{}v{:.2}",
                n.note, n.start_tick, n.duration_ticks, n.velocity
            )
        })
        .collect();
    let spans: Vec<String> = vocal_phrase_spans(&notes, &p)
        .iter()
        .map(|(a, b)| format!("{a}-{b}"))
        .collect();
    format!("{label} = {} | {}", rendered.join(" "), spans.join(" "))
}

/// As [`render`], but with an explicit section line count.
///
/// The default is 4 lines, which srdc lays out as a SINGLE group — so a
/// matrix built only from defaults leaves the multi-group path entirely
/// unpinned. That path is where the ordering hazard lives: `srdc.rs`
/// draws `aaba` once per group, and moving that draw inside the
/// `group_len >= 3` guard would make group 2 consume group 1's RNG draw,
/// flipping aaba<->aabc and silently rewriting melodies already saved in
/// users' projects.
fn render_lines(
    label: &str,
    style: VocalStyle,
    lines_count: u8,
    seed: u64,
) -> String {
    let mut p = VocalParams::default();
    p.style = style;
    p.contour = VocalContour::Arch;
    p.voice = VoiceType::Soprano;
    p.range = p.voice.default_range();
    p.lines = lines_count;
    p.draft = generate_lyrics(&p, seed);

    let notes = derive_vocal_with_motif(&chords(), &p, 480, 4, None, seed);
    let rendered: Vec<String> = notes
        .iter()
        .map(|n| {
            format!(
                "{}@{}+{}v{:.2}",
                n.note, n.start_tick, n.duration_ticks, n.velocity
            )
        })
        .collect();
    format!("{label} = {}", rendered.join(" "))
}

fn actual() -> String {
    let mut lines = Vec::new();
    for (si, &style) in STYLES.iter().enumerate() {
        for &seed in &[7u64, 42, 0xABCD] {
            lines.push(render(
                &format!("{si}/plain/{seed}"),
                style,
                VocalContour::Arch,
                VoiceType::Soprano,
                4,
                None,
                seed,
            ));
            lines.push(render(
                &format!("{si}/motif/{seed}"),
                style,
                VocalContour::Arch,
                VoiceType::Soprano,
                4,
                Some(&MOTIF),
                seed,
            ));
        }
    }
    // Contour, voice range and meter variations on the default style.
    for &contour in &[
        VocalContour::Rise,
        VocalContour::Fall,
        VocalContour::Wave,
        VocalContour::Flat,
    ] {
        lines.push(render(
            &format!("contour/{contour:?}"),
            VocalStyle::PopBallad,
            contour,
            VoiceType::Soprano,
            4,
            None,
            99,
        ));
    }
    for &voice in &[VoiceType::Bass, VoiceType::Alto, VoiceType::Tenor] {
        lines.push(render(
            &format!("voice/{voice:?}"),
            VocalStyle::Anthemic,
            VocalContour::Arch,
            voice,
            4,
            None,
            123,
        ));
    }
    for &bpb in &[2u32, 3, 6] {
        lines.push(render(
            &format!("meter/{bpb}"),
            VocalStyle::PopBallad,
            VocalContour::Arch,
            VoiceType::Soprano,
            bpb,
            None,
            2024,
        ));
    }
    // Multi-group srdc: 8 lines is two full groups, 7 is two groups with
    // a short tail — the two shapes that exercise the per-group draw.
    for (si, &style) in STYLES.iter().enumerate() {
        for &lines_count in &[7u8, 8] {
            lines.push(render_lines(
                &format!("{si}/lines{lines_count}"),
                style,
                lines_count,
                42,
            ));
        }
    }
    lines.join("\n")
}

#[test]
fn vocal_melody_output_matches_golden() {
    let actual = actual();
    if std::env::var("RESONANCE_PRINT_VOCAL_GOLDEN").is_ok() {
        println!("---8<---\n{actual}\n--->8---");
    }
    assert_eq!(
        actual.trim(),
        GOLDEN.trim(),
        "vocal melody output changed — this rewrites material already \
         persisted in user projects. Only update GOLDEN together with a \
         deliberate, documented change to the generator."
    );
}

